/**
 * @file dump_tables.c
 * @brief Writes every game table (data/generated/tables.h) to a text file,
 *        to check that the tables loaded from the ROM (src/romdata.c) are
 *        the ones tools/extract_data.py generates.
 *
 *   ff1-dump-ref <out>          the tables as generated by the extractor
 *   ff1-dump-rom <rom> <out>    the tables as src/romdata.c loads them
 *
 * The two files must be identical.
 */

#include <stdio.h>
#include <string.h>
#include "../data/generated/tables_decl.h"
#ifdef DUMP_FROM_ROM
#include "rom.h"
#include "romdata.h"
#endif

static void dump_bytes(FILE* f, const char* name, const void* p, size_t n) {
    const uint8_t* b = p;
    fprintf(f, "%s %u\n", name, (unsigned)n);
    for (size_t i = 0; i < n; i++) fprintf(f, "%02x", b[i]);
    fprintf(f, "\n");
}

static void dump_strings(FILE* f, const char* name, const char* const* s, size_t n) {
    fprintf(f, "%s %u strings\n", name, (unsigned)n);
    for (size_t i = 0; i < n; i++) {
        for (const char* c = s[i]; c && *c; c++) fprintf(f, "%02x", (uint8_t)*c);
        fprintf(f, "\n");
    }
}

int main(int argc, char** argv) {
#ifdef DUMP_FROM_ROM
    if (argc < 3) { fprintf(stderr, "usage: %s <rom> <out>\n", argv[0]); return 2; }
    RomStatus st = Rom_LoadFile(argv[1]);
    if (st != ROM_OK) { fprintf(stderr, "%s: %s\n", argv[1], Rom_StatusText(st)); return 1; }
    RomData_Load();
    const char* out = argv[2];
#else
    if (argc < 2) { fprintf(stderr, "usage: %s <out>\n", argv[0]); return 2; }
    const char* out = argv[1];
#endif
    FILE* f = fopen(out, "w");
    if (!f) return 1;
#define TABLE(n) dump_bytes(f, #n, n, sizeof(n));
#define STRTABLE(n) dump_strings(f, #n, (const char* const*)n, sizeof(n) / sizeof(n[0]));
#include "../data/generated/tables.h"
#undef TABLE
#undef STRTABLE
    fclose(f);
    return 0;
}
